+namespace sv_fb081e868a87430a8ce4931d66826762.Services;
+
+/// <summary>
+/// Scoped service (per-circuit) that polls for low-stock alerts and
+/// broadcasts updates to all subscribed components.
+/// </summary>
+public class InventoryAlertService : IDisposable
+{
+    private readonly WarehouseStateService _warehouseState;
+    private readonly Random _random = new();
+    private Timer? _timer;
+    private int _subscriberCount;
+
+    public int CurrentLowStockCount { get; private set; }
+
+    public event Action? OnAlertCountChanged;
+
+    public InventoryAlertService(WarehouseStateService warehouseState)
+    {
+        _warehouseState = warehouseState;
+        _warehouseState.OnChange += HandleWarehouseChanged;
+    }
+
+    /// <summary>
+    /// Simulates a database query returning random low-stock count.
+    /// </summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        return Task.FromResult(_random.Next(0, 16));
+    }
+
+    /// <summary>
+    /// Called by components that want polling active. Starts the timer
+    /// on first subscriber; subsequent subscribers just increment the count.
+    /// </summary>
+    public void StartPolling()
+    {
+        _subscriberCount++;
+        if (_subscriberCount == 1)
+        {
+            _timer = new Timer(async _ => await PollAsync(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
+        }
+    }
+
+    /// <summary>
+    /// Called when a subscriber leaves. Stops polling when no subscribers remain.
+    /// </summary>
+    public void StopPolling()
+    {
+        _subscriberCount = Math.Max(0, _subscriberCount - 1);
+        if (_subscriberCount == 0)
+        {
+            _timer?.Dispose();
+            _timer = null;
+        }
+    }
+
+    private async Task PollAsync()
+    {
+        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
+        CurrentLowStockCount = count;
+        OnAlertCountChanged?.Invoke();
+    }
+
+    private async void HandleWarehouseChanged()
+    {
+        if (_timer is not null)
+        {
+            // Immediately refresh when warehouse changes
+            await PollAsync();
+        }
+    }
+
+    public void Dispose()
+    {
+        _warehouseState.OnChange -= HandleWarehouseChanged;
+        _timer?.Dispose();
+    }
+}
